// Modern: querySelector / querySelectorAll (use CSS selectors)
const btn = document.querySelector('#submit-btn');
const inputs = document.querySelectorAll('input[type="text"]');
const cards = document.querySelectorAll('.card');
const firstLink = document.querySelector('nav a');

// Classic (still useful for performance)
const byId = document.getElementById('hero');
const byClass = document.getElementsByClassName('card'); // live HTMLCollection
const byTag = document.getElementsByTagName('li');        // live HTMLCollection

// Traversal
const parent = element.parentElement;
const children = element.children;           // HTMLCollection
const firstChild = element.firstElementChild;
const lastChild = element.lastElementChild;
const next = element.nextElementSibling;
const prev = element.previousElementSibling;

// Convert NodeList to Array for full array methods
const cardArray = Array.from(document.querySelectorAll('.card'));
cardArray.forEach(card => console.log(card.textContent));

// Reading content
const text  = el.textContent;  // all text, including hidden
const html  = el.innerHTML;    // HTML string (XSS risk!)
const outer = el.outerHTML;    // element itself + content

// Modifying content
el.textContent = 'New text content'; // safe — escapes HTML
el.innerHTML = '<strong>Bold</strong>'; // parses HTML (use carefully)

// Classes
el.classList.add('active', 'visible');
el.classList.remove('hidden');
el.classList.toggle('open');              // add if absent, remove if present
el.classList.replace('old', 'new');
const has = el.classList.contains('active'); // true/false

// Attributes
el.setAttribute('data-id', '42');
const id = el.getAttribute('data-id');   // '42'
el.removeAttribute('disabled');
const src = el.src;                      // direct property (faster)

// Styles
el.style.color = 'red';
el.style.backgroundColor = '#1a1a2e';

// Creating elements
const card = document.createElement('div');
card.className = 'card';
card.textContent = 'New Card';

// Inserting
parent.appendChild(card);              // at end
parent.prepend(card);                  // at start
parent.insertBefore(card, reference); // before reference
reference.insertAdjacentElement('afterend', card);

// Removing
card.remove();                // modern
parent.removeChild(card);    // classic

const btn = document.querySelector('#btn');

// Add event listener
function handleClick(event) {
  console.log('Clicked!');
  console.log(event.target);       // element that was clicked
  console.log(event.currentTarget); // element with the listener
  console.log(event.type);         // 'click'
  console.log(event.clientX, event.clientY); // mouse position

  event.preventDefault();          // stop default browser action
  event.stopPropagation();         // stop event bubbling up
}

btn.addEventListener('click', handleClick);
btn.removeEventListener('click', handleClick); // must be same reference!

// Common events
document.addEventListener('keydown', (e) => console.log(e.key, e.code));
input.addEventListener('input', (e) => console.log(e.target.value));
form.addEventListener('submit', (e) => { e.preventDefault(); /* ... */ });
window.addEventListener('resize', (e) => console.log(window.innerWidth));
document.addEventListener('scroll', (e) => console.log(window.scrollY));
img.addEventListener('load', () => console.log('Image loaded'));

// Without delegation: 1000 listeners for 1000 items = slow
document.querySelectorAll('.item').forEach(item => {
  item.addEventListener('click', handleItemClick); // ❌
});

// With delegation: 1 listener on parent handles ALL items
const list = document.querySelector('#product-list');

list.addEventListener('click', (event) => {
  // event.target is whatever was actually clicked
  const item = event.target.closest('.item'); // walk up to .item
  if (!item) return; // click was not on an item

  const id = item.dataset.id;
  const action = event.target.dataset.action; // e.g., 'delete'

  if (action === 'delete') deleteItem(id);
  else selectItem(id);
});

// Works for dynamically added items too!
function addItem(data) {
  const item = document.createElement('li');
  item.className = 'item';
  item.dataset.id = data.id;
  item.innerHTML = `
    ${data.name}
    <button data-action="delete">Delete</button>
  `;
  list.appendChild(item); // listener on parent catches it
}

// localStorage: persists after tab close
localStorage.setItem('user', JSON.stringify({ name: 'Alice', role: 'admin' }));
const user = JSON.parse(localStorage.getItem('user'));
localStorage.removeItem('user');
localStorage.clear();

// sessionStorage: cleared when tab closes
sessionStorage.setItem('draft', JSON.stringify(formData));

// IntersectionObserver: detect when element enters viewport
const observer = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      entry.target.classList.add('visible');
      observer.unobserve(entry.target); // stop watching
    }
  });
}, { threshold: 0.1 }); // 10% visible

document.querySelectorAll('.animate-on-scroll').forEach(el => {
  observer.observe(el);
});
